Explain why this lock-free queue has an ABA problem and rewrite it safely in C++20:

struct Node{int v; Node* next;};
std::atomic<Node*> head;
void push(Node* n){ n->next = head.load(); while(!head.compare_exchange_weak(n->next, n)); }
Node* pop(){ Node* h = head.load(); while(h && !head.compare_exchange_weak(h, h->next)); return h; }
